  expires_at: Scalars['String']['output'];
  issued_at: Scalars['String']['output'];
  /** LOGIN, PASSWORD_RESET, WHATSAPP_SIGNUP, WHATSAPP_CHANGE, EMAIL_VERIFICATION, PASSWORD_CHANGE, ACCOUNT_DELETION or PORTAL_LOGIN. */
