export type UpdateAppSettingsInput = {
  /** Whether a host must verify an attendee's name and phone over OTP before marking them present by hand. The door scan is proof on its own and is never gated by this. */
  attendance_otp_required?: InputMaybe<Scalars['Boolean']['input']>;
  /** How many hours after an Auto Pod is rolled out its venue, host and club admin have to all enrol before it is released (1-720). */
  auto_pod_assignment_expiry_hours?: InputMaybe<Scalars['Int']['input']>;
  /** Account Health points a venue or host loses by withdrawing from an Auto Pod (0-100, 0 disables the penalty). */
  auto_pod_cancel_health_penalty?: InputMaybe<Scalars['Int']['input']>;
  /** How many days ahead a venue is shown its free slots when accepting an Auto Pod (1-60). */
  auto_pod_slot_window_days?: InputMaybe<Scalars['Int']['input']>;
  /** How many hours an Auto Pod waits for a venue before it leaves venues' lists and expires (1-720). */
  auto_pod_venue_expiry_hours?: InputMaybe<Scalars['Int']['input']>;
  /** Account Health points a club admin loses for filing a Request Change (0-10, 0 disables it). */
  club_admin_change_request_health_penalty?: InputMaybe<Scalars['Int']['input']>;
  /** CUSTOM anchor (ISO). Saving it stamps custom_time_set_at server-side. */
  custom_time?: InputMaybe<Scalars['String']['input']>;
  date_format?: InputMaybe<Scalars['String']['input']>;
  /** Days a Create-Pod draft is kept before auto-deletion (min 1). */
  draft_retention_days?: InputMaybe<Scalars['Int']['input']>;
  /** Account Health points a host loses for filing a Request Change (0-10, 0 disables it). */
  host_change_request_health_penalty?: InputMaybe<Scalars['Int']['input']>;
  jwt_expires_in?: InputMaybe<Scalars['String']['input']>;
  jwt_no_expiry?: InputMaybe<Scalars['Boolean']['input']>;
  /** Max Backout attempts a user gets per pod (min 1). */
  max_backout_attempts?: InputMaybe<Scalars['Int']['input']>;
  /** Minimum age to use the app, in whole years (1-120). */
  min_signup_age?: InputMaybe<Scalars['Int']['input']>;
  /** Whether the sweep auto-cancels an upcoming pod whose finances are negative, refunding attendees under the venue's cancellation policy. */
  pod_auto_cancel_enabled?: InputMaybe<Scalars['Boolean']['input']>;
  /** How many hours before a pod's start the auto-cancel finance check runs (1-8760). */
  pod_auto_cancel_lead_hours?: InputMaybe<Scalars['Int']['input']>;
  /** Whether a cancellation holds its refunds until the pod's start time instead of paying them out at once. */
  pod_cancel_refund_hold?: InputMaybe<Scalars['Boolean']['input']>;
  /** How often, in hours, the host and club admins of an at-risk pod are re-alerted (1-168). */
  pod_cancel_risk_alert_hours?: InputMaybe<Scalars['Int']['input']>;
  /** How many hours before a pod's start it is watched for cancellation risk (1-8760). */
  pod_cancel_risk_window_hours?: InputMaybe<Scalars['Int']['input']>;
  /** How many hours after a pod ends the host is reminded to complete it (1-8760). */
  pod_complete_reminder_hours?: InputMaybe<Scalars['Int']['input']>;
  /** How many hours after a pod ends its host has to complete it (1-8760). */
  pod_complete_timeout_hours?: InputMaybe<Scalars['Int']['input']>;
  /** How many hours after a pod ends everyone who was there is asked how it went (0-8760). */
  pod_feedback_delay_hours?: InputMaybe<Scalars['Int']['input']>;
  /** How many hours before a pod starts its attendees are reminded (1-8760). */
  pod_reminder_lead_hours?: InputMaybe<Scalars['Int']['input']>;
  /** The biggest discount any multi-ticket tier on a pod may give, in whole % (1-99). */
  ticket_discount_max_pct?: InputMaybe<Scalars['Int']['input']>;
  time_format?: InputMaybe<Scalars['String']['input']>;
  time_source?: InputMaybe<TimeSource>;
  time_zone?: InputMaybe<Scalars['String']['input']>;
  /** Account Health points deducted from a venue when its owner cancels a pod booked there (0-100, 0 disables the penalty). */
  venue_cancel_health_penalty?: InputMaybe<Scalars['Int']['input']>;
  /** Account Health points a venue loses for filing a Request Change (0-10, 0 disables it). */
  venue_change_request_health_penalty?: InputMaybe<Scalars['Int']['input']>;
  /** How many hours before the requested slot an unanswered venue slot request is chased (1-8760). */
  venue_slot_reminder_lead_hours?: InputMaybe<Scalars['Int']['input']>;
};

